"""A 1-D corridor: walk right to the goal before the step cap (CORE-03)."""

from collections.abc import Mapping

import numpy as np

from rllab.core import SOLO, ActionSpace, Env, Rewards, StepResult, TeamSpec

_DEFAULT_REWARDS = Rewards()
_N_ACTIONS = 2
_AGENT_CELL = 1
_GOAL_CELL = 3


class Corridor(Env):
    """One agent, two actions (0 left, 1 right), a one-hot position view."""

    def __init__(
        self, *, length: int = 10, max_steps: int = 50, rewards: Rewards = _DEFAULT_REWARDS
    ) -> None:
        if length < 2:
            raise ValueError(f"length must be >= 2, got {length}")
        if max_steps < 1:
            raise ValueError(f"max_steps must be >= 1, got {max_steps}")
        self.teams: Mapping[str, TeamSpec] = {
            SOLO: TeamSpec(1, (length,), ActionSpace("discrete", n=_N_ACTIONS))
        }
        self.board = "grid"
        self._length = length
        self._max_steps = max_steps
        self._rewards = rewards
        self._position = 0
        self._steps = 0
        self._score = 0.0
        self._over = False

    def reset(self, seed: int) -> tuple[dict[str, np.ndarray], dict[str, float]]:
        """Start at cell 0; the corridor has no randomness, so the seed changes nothing."""
        self._position = 0
        self._steps = 0
        self._score = 0.0
        self._over = False
        return self._obs(), self._info()

    def step(self, actions: Mapping[str, np.ndarray]) -> StepResult:
        if self._over:
            raise RuntimeError("step called after the game is over; call reset first")
        action = _check_action(actions)
        self._position = min(max(self._position + (1 if action == 1 else -1), 0), self._length - 1)
        self._steps += 1
        goal = self._position == self._length - 1
        reward = self._rewards.step + (self._rewards.food if goal else 0.0)
        self._score += 1.0 if goal else 0.0
        truncated = not goal and self._steps >= self._max_steps
        self._over = goal or truncated
        return StepResult(
            obs=self._obs(),
            reward={SOLO: np.array([reward], dtype=np.float32)},
            done={SOLO: np.array([goal])},
            terminated=goal,
            truncated=truncated,
            info=self._info(),
        )

    def frame(self) -> np.ndarray:
        cells = np.zeros((1, self._length), dtype=np.int8)
        cells[0, -1] = _GOAL_CELL
        cells[0, self._position] = _AGENT_CELL
        return cells

    def _obs(self) -> dict[str, np.ndarray]:
        view = np.zeros((1, self._length), dtype=np.float32)
        view[0, self._position] = 1.0
        return {SOLO: view}

    def _info(self) -> dict[str, float]:
        return {"steps": float(self._steps), f"score:{SOLO}": self._score, "score": self._score}


def _check_action(actions: Mapping[str, np.ndarray]) -> int:
    if SOLO not in actions:
        raise ValueError(f"actions must name team {SOLO!r}, got {sorted(actions)}")
    action = np.asarray(actions[SOLO])
    if action.shape != (1,):
        raise ValueError(f"actions[{SOLO!r}] must have shape (1,), got {action.shape}")
    value = action[0]
    if not np.isfinite(value) or value != int(value) or not 0 <= value < _N_ACTIONS:
        raise ValueError(f"action must be 0 (left) or 1 (right), got {value}")
    return int(value)

