@pytest.mark.parametrize(
    ("actions", "match"),
    [
        ({"other": np.array([1], dtype=np.int64)}, "must name team"),
        ({SOLO: np.array([1, 0], dtype=np.int64)}, "must have shape"),
        ({SOLO: np.array(1, dtype=np.int64)}, "must have shape"),
        ({SOLO: np.array([2], dtype=np.int64)}, "0 \\(left\\) or 1"),
        ({SOLO: np.array([-1], dtype=np.int64)}, "0 \\(left\\) or 1"),
        ({SOLO: np.array([np.nan])}, "0 \\(left\\) or 1"),
        ({SOLO: np.array([0.5])}, "0 \\(left\\) or 1"),
    ],
)
def test_bad_actions_raise_value_error(actions: dict[str, np.ndarray], match: str) -> None:
    env = Corridor()
    env.reset(0)
    with pytest.raises(ValueError, match=match):
        env.step(actions)


@pytest.mark.parametrize(
    ("length", "max_steps", "match"), [(1, 50, "length"), (10, 0, "max_steps")]
)
def test_bad_sizes_raise_value_error(length: int, max_steps: int, match: str) -> None:
    with pytest.raises(ValueError, match=match):
        Corridor(length=length, max_steps=max_steps)

